using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class LoyaltyDiscountAcceptanceTests
{
    // Bronze customer is charged the Bronze price
    [Theory]
    [InlineData(10000, 9500)]
    [InlineData(7, 7)]
    public void Bronze_customer_is_charged_the_Bronze_price(int subtotalCents, int expectedTotalCents)
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, LoyaltyTier.Bronze));

        Assert.Equal(expectedTotalCents, quote.TotalCents);
    }
}
EOF
